declare -x CARAPACE_SHELL_BUILTINS="$(compgen -b)"
declare -x CARAPACE_SHELL_FUNCTIONS="$(compgen -A function)"
declare -x CARAPACE_SHELL=bash

function _carapace_completer {
  export COMP_LINE
  export COMP_POINT
  export COMP_TYPE
  export COMP_WORDBREAKS

  local command="${COMP_WORDS[0]}" nospace data compline="${COMP_LINE:0:${COMP_POINT}}"

  data=$(xargs carapace "${command}" bash <<<"${compline}''" 2> /dev/null) \
    || data=$(xargs carapace "${command}" bash <<<"${compline}'" 2> /dev/null) \
    || data=$(xargs carapace "${command}" bash <<<"${compline}\"" 2> /dev/null)

  COMPREPLY=()
  IFS=$'\001' read -rd '' nospace data <<< "${data}"
  [[ "${data}" != $'\n' ]] && mapfile -t COMPREPLY <<<"${data}" && unset 'COMPREPLY[-1]'
  [[ "${nospace}" == 'true' ]] && compopt -o nospace
}

complete -o noquote -F _carapace_completer "acpi" "acpid" "act" "adb" "age" "agg" "alsamixer" "ansible" "ansible-config" "ansible-console" "ansible-creator" "ansible-doc" "ansible-galaxy" "ansible-inventory" "ansible-playbook" "ansible-pull" "ansible-vault" "ant" "apk" "apko" "aplay" "apptainer" "apropos" "apt" "apt-cache" "apt-get" "aqua" "ar" "archlinux-java" "arecord" "argo" "argocd" "aria2c" "artisan" "asciinema" "atuin" "autoconf" "avdmanager" "awk" "aws" "az" "baobab" "base32" "base64" "basename" "bash" "bash-language-server" "bat" "batdiff" "batgrep" "batman" "bats" "bazel" "bc" "benthos" "black" "bloop" "bluetoothctl" "boundary" "brew" "brotli" "bru" "btop" "buildctl" "bun" "bunx" "but" "cal" "calibre" "capslock" "carapace" "cargo" "cargo-clippy" "cargo-fmt" "cargo-metadata" "cargo-rm" "cargo-set-version" "cargo-upgrade" "cargo-watch" "cat" "cdebug" "cekit" "cfdisk" "charm" "chcpu" "chdman" "cheese" "chezmoi" "chgrp" "chmod" "chown" "chpasswd" "chroma" "chromium" "chroot" "chsh" "circleci" "cksum" "clamav-config" "clamav-milter" "clambc" "clamconf" "clamd" "clamdscan" "clamdtop" "clamonacc" "clamscan" "clamsubmit" "clion" "cmus" "code" "code-insiders" "codecov" "colima" "comm" "compare" "composite" "conda" "conda-content-trust" "conda-env" "conky" "consul" "coredumpctl" "cosign" "cp" "crc" "crush" "csplit" "csview" "cue" "cura" "curl" "cut" "d2" "dagger" "darktable" "darktable-cli" "dart" "datagrip" "dataspell" "date" "dbt" "dc" "dd" "deadcode" "delta" "deno" "devbox" "devcontainer" "devpod" "df" "dfc" "dict" "diff" "diff3" "dig" "dir" "dircolors" "direnv" "dirname" "dive" "dlv" "dmenu" "dmesg" "dms" "dnf" "dngconverter" "dnsmasq" "doas" "docker" "docker-buildx" "docker-compose" "docker-scan" "dockerd" "doctl" "doing" "dos2unix" "downgrade" "dpkg" "du" "ebook-convert" "egrep" "electron" "elvish" "env" "envsubst" "exa" "exercism" "expand" "expr" "eza" "faas-cli" "factor" "fakechroot" "fakeroot" "fastfetch" "fc-cache" "fc-cat" "fc-conflist" "fc-list" "fd" "fdi